    while args and args[0] in ('--project-directory', '--env-file', '-f'):
        args = args[2:]
    action = args[0]
    if os.environ.get('FAKE_FAIL') == action:
        sys.exit(17)
    if action in ('version', 'config', 'pull', 'create'):
        pass
    elif action == 'ps':
        print('fake-authority')
