        state['running'] = True
    elif action == 'run':
        script = args[-1]
        if 'test -s' in script:
            sys.exit(0 if (root / 'data/collab.db').exists() else 1)
        elif 'tar -xf' in script:
            if os.environ.get('FAKE_FAIL') == 'extract':
                sys.exit(18)
