        elif '已有数据库' in script:
            if (root / 'data/collab.db').exists() and not (root / 'data/account_authority.key').exists():
                sys.exit(20)
        else:
            raise RuntimeError('unhandled run')
    else:
        raise RuntimeError(f'unhandled compose {args}')
elif args[0] == 'inspect':
